# owner: platform
"""Short absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed

Marks = Iterable[Mark]


def _check_owner(student: Student, marks: list) -> None:
    """Refuse marks that belong to someone else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id!r} is "
                f"not {student.student_id!r}"
            )


def _plural(count: int) -> str:
    return "1 day" if count == 1 else f"{count} days"


def _compose(student: Student, days: list) -> str:
    name = f"{student.first_name} {student.last_name}"
    dates = ", ".join(day.isoformat() for day in days)
    return (
        "Dear parent or guardian,\n\n"
        f"{name} missed {_plural(len(days))}: {dates}."
    )


# ---
def absence_notice(student: Student, marks: Marks) -> str:
    """Text notice naming the student, count and dates."""
    marks = list(marks)
    _check_owner(student, marks)
    days = days_missed(marks)
    if not days:
        raise ProjectError("no absences to write about")
    return _compose(student, days)
